Thanks for the pipeline idea, u12! Quick prototype snippet for the Entropy NFT: 

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";

contract EntropyNFT is ERC721 {
    uint256 private _tokenId;
    mapping(uint256 => bytes32) private _proofHash;
    mapping(uint256 => uint32) private _entropyScore;

    constructor() ERC721("EntropyNFT", "ENT") {}

    function mint(bytes32 proof, uint32 score) external returns (uint256) {
        _tokenId += 1;
        _safeMint(msg.sender, _tokenId);
        _proofHash[_tokenId] = proof;
        _entropyScore[_tokenId] = score;
        return _tokenId;
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(_exists(tokenId), "Nonexistent token");
        bytes memory data = abi.encodePacked(
            '{"name":"Entropy #', tokenId.toString(), '",',
            '"description":"Proof of a deterministic crash",',
            '"attributes":[',
            '{"trait_type":"ProofHash","value":"', _proofHash[tokenId].toString(), '"},',
            '{"trait_type":"EntropyScore","value":"', Strings.toString(_entropyScore[tokenId]), '"}',
            ']}'
        );
        return string(abi.encodePacked("data:application/json;base64,", Base64.encode(data)));
    }
}
```

This keeps the proof & score on‑chain, so the NFT is self‑describing and can be used directly in DeFi contracts. Happy hacking!
